window.ScripturaLexicons.BDAG_PART_0234 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-01\" data-source=\"BDAG\" data-search=\"μετοπωρινός, όν adjetivo outonal; de outono BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετοπωρινός, όν</td><td>adjetivo</td><td>outonal; de outono</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-02\" data-source=\"BDAG\" data-search=\"μετοχή, ῆς, ἡ substantivo feminino participação; partilha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετοχή, ῆς, ἡ</td><td>substantivo feminino</td><td>participação; partilha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-03\" data-source=\"BDAG\" data-search=\"μέτοχος, ον adjetivo e substantivo participante; companheiro; sócio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέτοχος, ον</td><td>adjetivo e substantivo</td><td>participante; companheiro; sócio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-04\" data-source=\"BDAG\" data-search=\"μετρέω verbo medir; repartir; distribuir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετρέω</td><td>verbo</td><td>medir; repartir; distribuir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-05\" data-source=\"BDAG\" data-search=\"μετρητής, οῦ, ὁ substantivo masculino medida para líquidos; cerca de 40 litros BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετρητής, οῦ, ὁ</td><td>substantivo masculino</td><td>medida para líquidos; cerca de 40 litros</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-06\" data-source=\"BDAG\" data-search=\"μετριοπαθέω verbo moderar sentimentos; tratar com brandura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετριοπαθέω</td><td>verbo</td><td>moderar sentimentos; tratar com brandura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-07\" data-source=\"BDAG\" data-search=\"μέτριος, ία, ιον adjetivo moderado; comedido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέτριος, ία, ιον</td><td>adjetivo</td><td>moderado; comedido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-08\" data-source=\"BDAG\" data-search=\"μετρίως advérbio moderadamente; bastante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετρίως</td><td>advérbio</td><td>moderadamente; bastante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-09\" data-source=\"BDAG\" data-search=\"μέτρον, ου, τό substantivo neutro medida; quantidade; extensão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέτρον, ου, τό</td><td>substantivo neutro</td><td>medida; quantidade; extensão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-10\" data-source=\"BDAG\" data-search=\"μέτωπον, ου, τό substantivo neutro testa; fronte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέτωπον, ου, τό</td><td>substantivo neutro</td><td>testa; fronte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-11\" data-source=\"BDAG\" data-search=\"μέχρι preposição e conjunção até; até o ponto de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέχρι</td><td>preposição e conjunção</td><td>até; até o ponto de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-12\" data-source=\"BDAG\" data-search=\"μή partícula negativa não; proibição; negação enfática BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μή</td><td>partícula negativa</td><td>não; proibição; negação enfática</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-13\" data-source=\"BDAG\" data-search=\"μήγε partícula composta caso contrário; ver γέ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήγε</td><td>partícula composta</td><td>caso contrário; ver γέ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-14\" data-source=\"BDAG\" data-search=\"μηδαμῶς advérbio de modo algum; certamente não BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηδαμῶς</td><td>advérbio</td><td>de modo algum; certamente não</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-15\" data-source=\"BDAG\" data-search=\"μηδέ partícula disjuntiva negativa nem; e não; nem mesmo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηδέ</td><td>partícula disjuntiva negativa</td><td>nem; e não; nem mesmo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-16\" data-source=\"BDAG\" data-search=\"μηδείς, μηδεμία, μηδέν adjetivo e pronome indefinido negativo nenhum; ninguém; nada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηδείς, μηδεμία, μηδέν</td><td>adjetivo e pronome indefinido negativo</td><td>nenhum; ninguém; nada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-17\" data-source=\"BDAG\" data-search=\"μηδέποτε advérbio nunca BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηδέποτε</td><td>advérbio</td><td>nunca</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-18\" data-source=\"BDAG\" data-search=\"μηδέπω advérbio ainda não BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηδέπω</td><td>advérbio</td><td>ainda não</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-19\" data-source=\"BDAG\" data-search=\"Μῆδος, ου, ὁ substantivo masculino medo; habitante da Média BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μῆδος, ου, ὁ</td><td>substantivo masculino</td><td>medo; habitante da Média</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0234-20\" data-source=\"BDAG\" data-search=\"μηθαμῶς advérbio remissivo ver μηδαμῶς BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηθαμῶς</td><td>advérbio remissivo</td><td>ver μηδαμῶς</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0234-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοπωρινός, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετοπωρινός</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">μετά</span> + <span class=\"greek\">ὀπώρα</span> “fim do verão” = “depois do fim do verão” ou “outono”; Hes., Thu. e outros; Philostrat., Vi. Apoll. 5, 6 p. 168, 24; Philo), outonal: <span class=\"greek\">καιροὶ</span> <span class=\"greek\">μ</span>., o outono 1 Cl 20:9.—DELG s.v. <span class=\"greek\">ὀπώρα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοχή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετοχή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (ver <span class=\"greek\">μετέχω</span> e a entrada seguinte; Hdt.+; papiros; Ps 121:3; PsSol 14:6; Philo, Leg. All. 1, 22), compartilhamento, participação (BGU 1123, 11 [I a.C.]; PLond III, 941, 8 p. 119 [227 d.C.] e outros) <span class=\"greek\">τίς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">δικαιοσύνῃ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνομίᾳ</span>; que têm em comum a justiça e a iniquidade? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:14</a> (há um paralelo puramente formal a 2 Cor 6:14–16 em Himerius, Or. [Ecl.] 3, 6 <span class=\"greek\">ποῦ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">συμβαίνει</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μίγνυται</span> <span class=\"greek\">ἡδονὴ</span> <span class=\"greek\">πόνοις</span>, <span class=\"greek\">καρτηρία</span> <span class=\"greek\">τρυφῇ</span>, <span class=\"greek\">ἀκαδημία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πόρναι</span>, <span class=\"greek\">φιλοσοφία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πότος</span>, <span class=\"greek\">σωφρονούντων</span> <span class=\"greek\">βίος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀκόλαστα</span> <span class=\"greek\">μειράκια</span>; = haverá realmente algo em comum entre prazer e labor, perseverança e luxo, escola e prostitutas, estudo e festas, vida prudente e juventude indisciplinada?).—DELG s.v. 1 <span class=\"greek\">ἔχω</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτοχος, ον</h1><div class=\"entry-meta\"><span>adjetivo e substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέτοχος</span>, <span class=\"greek\">ον</span> (ver <span class=\"greek\">μετέχω</span> e o verbete anterior; Eur., Hdt. e outros; papiros, LXX, En; TestBenj 2:5).</p><p class=\"entry-text\">① Que compartilha ou participa de, como adjetivo, com genitivo da pessoa ou da coisa (Hdt. 3, 52; Pr 29:10; EpArist 207; SibOr 12, 174; Iren. 1, 13, 1 [Harv. I 118, 1]; Theoph. Ant. 3, 30 [p. 268, 21]) <span class=\"greek\">κλήσεως</span> <span class=\"greek\">ἐπουρανίου</span>, participantes de uma vocação celestial <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:1</a>. Da disciplina do Senhor 12:8. Do Espírito Santo 6:4. Das promessas 1 Cl 34:7. Participar da oração IEph 11:2. <span class=\"greek\">μ</span>. <span class=\"greek\">εἶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">αὐτοῦ</span>, participas do pecado dele Hm 4, 1, 9.—<span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, participante de Cristo (cf. Kaibel 654, 5 <span class=\"greek\">πρόσθεν</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">θνητή</span>, <span class=\"greek\">νῦν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">μέτοχος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:14</a>. Talvez, porém, essa passagem pertença à acepção 2.</p><p class=\"entry-text\">② Como substantivo <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>., sócio (comercial), companheiro (Ps.-Demosth. 61, 31; PPetr III, 37a II, 7 [259 a.C.]; BGU 1123, 4; BASP XXXIII p. 131 linha 5, sobre escriturários do censo “associados” [189 d.C.]; outros papiros; En 104:6; TestBenj 2:5; Orig., C. Cels. 6, 79, 25; Did., Gen. 213, 20 [talvez sob 1, acima]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:7</a>, em sentido comercial comum nos papiros; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:9</a> (Ps 44:8). WWuellner, The Meaning of ‘Fishers of Men’ ’67.—New Docs 1, 84f. DELG s.v. 1 <span class=\"greek\">ἔχω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετρέω</span>, futuro na 2ª pessoa singular <span class=\"greek\">μετρήσεις</span> Num 35:5; 1º aoristo <span class=\"greek\">ἐμέτρησα</span>. Passivo: 1º futuro <span class=\"greek\">μετρηθήσομαι</span>; perfeito na 3ª pessoa singular <span class=\"greek\">μεμέτρηται</span> Wsd 4:8 (de <span class=\"greek\">μέτρον</span>; Hom.+), em geral, “medir”.</p><p class=\"entry-text\">① Tomar as dimensões de, medir.</p><p class=\"entry-text\">ⓐ Espacialmente, com acusativo da coisa: <span class=\"greek\">τὸν</span> <span class=\"greek\">ναόν</span>, medir o templo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:1</a> (PKetter, Past. Bonus 52, ’41, 93–99). <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>, medir a cidade 21:15. <span class=\"greek\">αὐλήν</span> 11:2. <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανόν</span> 16:2 (Is 40:12; ApcEsdr 7:5 p. 32, 16 Tdf.). Com o instrumento de medição no dativo (Ex 16:18): <span class=\"greek\">τῷ</span> <span class=\"greek\">καλάμῳ</span>, medir com a vara <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:16</a>; cf. 11:1. A medida obtida é expressa pelo genitivo de qualidade: <span class=\"greek\">ἐμέτρησεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τεῖχος</span> <span class=\"greek\">ἑκατὸν</span> <span class=\"greek\">τεσσεράκοντα</span> <span class=\"greek\">τεσσάρων</span> <span class=\"greek\">πηχῶν</span>, mediu a muralha (e ela tinha) 144 côvados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:17</a>; também por <span class=\"greek\">ἐπί</span> com genitivo, versículo 16, em que uma variante de leitura apresenta <span class=\"greek\">ἐπί</span> com acusativo (quanto a este último, cf. Da 3:47).</p><p class=\"entry-text\">ⓑ Não espacialmente: <span class=\"greek\">αὐτοὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">μετροῦντες</span>, eles se medem (isto é, avaliam) uns pelos outros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:12</a>. <span class=\"greek\">ἐμαυτὸν</span> <span class=\"greek\">μετρῶ</span>, mantenho-me dentro dos limites ITr 4:1 (Sotades Mar. [III a.C.] 10, 8 Diehl = Coll. Alex. n.º 9, 8 p. 242 <span class=\"greek\">ἡ</span> <span class=\"greek\">σωφροσύνη</span> <span class=\"greek\">πάρεστιν</span>, <span class=\"greek\">ἂν</span> <span class=\"greek\">μετρῇς</span> <span class=\"greek\">σεαυτόν</span>; TestJos 10:6 <span class=\"greek\">ἐμέτρουν</span> <span class=\"greek\">ἐμαυτόν</span>).</p><p class=\"entry-text\">② Dar em quantia medida, distribuir, repartir, atribuir <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, algo a alguém (Eur.; Ps.-Demosth. 46, 20; PPetr III, 89, 2; PTebt 459, 4 [5 a.C.] <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">περισσὸν</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">μέτρησον</span> <span class=\"greek\">αὐτοῖς</span>), na expressão proverbial <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">μέτρῳ</span> <span class=\"greek\">μετρεῖτε</span>, <span class=\"greek\">μετρηθήσεται</span> <span class=\"greek\">ὑμῖν</span>, a medida que usais será aquela com que sereis medidos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:24</a>. Igualmente, mas sem <span class=\"greek\">ἐν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:38</a>, variante de leitura (Maximus Tyr. 27, 7b faz um jogo de palavras com <span class=\"greek\">μετρεῖ</span>…<span class=\"greek\">μετρεῖται</span>.—Philo, Rer. Div. Her. 229 <span class=\"greek\">μέτροις</span> <span class=\"greek\">μεμέτρηται</span>.—O passivo = “receber a própria porção”: Jos., Bell. 3, 185).—Em 1 Cl 13:2 a sentença é <span class=\"greek\">ᾧ</span> <span class=\"greek\">μέτρῳ</span> <span class=\"greek\">μετρεῖτε</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">μετρηθήσεται</span> <span class=\"greek\">ὑμῖν</span>. O texto de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:38</a> tem <span class=\"greek\">ᾧ</span> <span class=\"greek\">μέτρῳ</span> <span class=\"greek\">μετρεῖτε</span>, <span class=\"greek\">ἀντιμετρηθήσεται</span> <span class=\"greek\">ὑμῖν</span>, repetido literalmente em Pol 2:3.—B. 877f. DELG s.v. <span class=\"greek\">μέτρον</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετρητής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετρητής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span>, unidade de capacidade para líquidos de cerca de 40 litros, medida, originária da Ática (Demosth. 42, 20; Aristot. HA 8, 9; Polyb. 2, 15, 1; inscrições [desde o IV séc. a.C.]; papiros, LXX; TestSol 16:7 P; EpArist 76; empréstimo no rabínico), de capacidade semelhante à do hebraico <span class=\"hebrew\" dir=\"rtl\">בַּת</span>, contendo 72 sextarii (Jos., Ant. 8, 57) ou pintas = 39.39 litros, aproximadamente nove galões (ver FHultsch, Griech. u. röm. Metrologie^2 1882, 101f; 108f; 703). Como medida de vinho (SIG 672, 54 [162–160 a.C.]; OGI 266, 4; Gk. Pap. fr. Gurob [1921] 8, 14; frequentemente nos papiros como medida de vinho; 1 Esdr 8:20; Bel 3 Theod.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:6</a>.—DELG s.v. <span class=\"greek\">μέτρον</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετριοπαθέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετριοπαθέω</span> (<span class=\"greek\">μέτριος</span>, <span class=\"greek\">πάσχω</span> por meio de -<span class=\"greek\">παθής</span>; Sext. Emp., Pyrrh. Hyp. 3, 235; 236; Dositheus 71, 11; Philo, Abr. 257; Jos., Ant. 12, 128. <span class=\"greek\">μετριοπαθής</span> e <span class=\"greek\">μετριοπάθεια</span> são mais frequentes), moderar os próprios sentimentos, tratar com brandura, com dativo de pessoa: <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀγνοοῦσιν</span>, tratar com brandura aqueles que pecam por ignorância (<span class=\"greek\">ἀγνοέω</span> 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:2</a>.—DELG s.v. <span class=\"greek\">πάσχω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτριος, ία, ιον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέτριος</span>, <span class=\"greek\">ία</span>, <span class=\"greek\">ιον</span> (ver <span class=\"greek\">μέτρον</span> e a entrada seguinte; Hes., Thu.+; também SIG 783, 53; POxy 120, 7; 1117, 19), superlativo <span class=\"greek\">μετριώτατος</span> (Tat. 11, 2; Ath. 11, 2), moderado; <span class=\"greek\">μέτρια</span> <span class=\"greek\">νοεῖν</span>, ser moderado, exercer autocontrole 1 Cl 1:3 (<span class=\"greek\">μέτρια</span> <span class=\"greek\">φρονεῖν</span> no mesmo sentido: Diod S 23, 15, 4; 8).—DELG s.v. <span class=\"greek\">μέτρον</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετρίως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετρίως</span>, advérbio de <span class=\"greek\">μέτριος</span> (Eur., Hdt. e outros; Plut., Tit. Flam. 373 [9, 5] <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>.; UPZ 71, 5 [152 a.C.]; PRyl 150, 9 <span class=\"greek\">ὕβρισεν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μετρίως</span>; PGiss 17, 5 <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>.; Sb 4323, 2 <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>.; 2 Macc 15:38; EpArist 197), moderadamente, um tanto; <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>., grandemente (Diod S 18, 45, 4; 20, 83, 2; Plut., Mor. 838f; Procop. Soph., Ep. 5; Philo; Jos., Ant. 15, 194; 276; ver <span class=\"greek\">μέτριος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:12</a>. A lítotes significa: receberam não pequeno consolo.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτρον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέτρον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hom.+; inscrições, papiros, LXX, En, TestSol 15:5; TestAbr A; Test12Patr; GrBar 6:7; ApcMos 13; Sib Or 3, 237; EpArist, Philo; Jos., Ant. 13, 294, C. Ap. 2, 216; Just., 112, 4; Tat. 27, 3; Ath.), em geral, “aquilo com que se mede qualquer coisa”.</p><p class=\"entry-text\">① Instrumento de medição, medida.</p><p class=\"entry-text\">ⓐ De medidas de capacidade: <span class=\"greek\">ἐν</span> <span class=\"greek\">μέτρῳ</span> <span class=\"greek\">μετρεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:24</a>; 1 Cl 13:2b. <span class=\"greek\">μέτρῳ</span> <span class=\"greek\">μετρεῖν</span> (Maximus Tyr. 32, 9c; 35, 2i) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:38b</a>; 1 Cl 13:2a; Pol 2:3. Com acumulação de qualificativos: <span class=\"greek\">μ</span>. <span class=\"greek\">καλὸν</span> <span class=\"greek\">πεπιεσμένον</span> <span class=\"greek\">σεσαλευμένον</span> <span class=\"greek\">ὑπερεκχυννόμενον</span>, boa medida, recalcada, sacudida, transbordante <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:38a</a>. Em figura: <span class=\"greek\">πληροῦν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τινός</span>, completar uma medida que outra pessoa encheu em parte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:32</a>.</p><p class=\"entry-text\">ⓑ De medida linear <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:15</a>. <span class=\"greek\">μέτρον</span> <span class=\"greek\">ἀνθρώπου</span>, <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἀγγέλου</span>, medida humana, também usada por anjos, versículo 17.</p><p class=\"entry-text\">② Resultado da medição, quantidade, número.</p><p class=\"entry-text\">ⓐ Literalmente, <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">δρόμων</span> <span class=\"greek\">φυλάσσειν</span>, observar a medida de seus percursos diários Dg 7:2.</p><p class=\"entry-text\">ⓑ Figuradamente (Maximus Tyr. 40, 3c <span class=\"greek\">ὑγείας</span> <span class=\"greek\">μ</span>.; Alex. Aphr., Quaest. 3, 12 II/2 p. 102, 2 <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>; Ath. 32, 2 <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">μ</span>.; 33, 1 <span class=\"greek\">μ</span>. <span class=\"greek\">ἐπιθυμίας</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">παιδοποιία</span>) <span class=\"greek\">ὡς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐμέρισεν</span> <span class=\"greek\">μέτρον</span> <span class=\"greek\">πίστεως</span>, conforme Deus distribuiu a medida da fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:3</a> (CCranfield, NTS 8, ’62, 345–51: Cristo é a medida da fé). <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">ἑκάστῳ</span> <span class=\"greek\">ἐδόθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">δωρεᾶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, a graça foi dada a cada um segundo a medida (dela) concedida por Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:7</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κανόνος</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐμέρισεν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">μέτρου</span>, conforme a medida do limite (= dentro dos limites) que Deus nos atribuiu (como medida) (ver B-D-F §294, 5; Rob. 719) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:13</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐνέργειαν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μέτρῳ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">ἑκάστου</span> <span class=\"greek\">μέρους</span>, conforme a capacidade funcional de cada parte individual <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:16</a> (<span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. como em Synes., Ep. 12 p. 171c). <span class=\"greek\">καταντᾶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἡλικίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πληρώματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, alcançar a medida da idade madura (ou estatura da plenitude) de Cristo, versículo 13 (ver <span class=\"greek\">ἡλικία</span> 2a e cf. <span class=\"greek\">μ</span>. <span class=\"greek\">ἡλικίας</span> Plut., Mor. 113d; <span class=\"greek\">μ</span>. <span class=\"greek\">ἥβης</span> Il. 11, 225; Od. 11, 317).—<span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μέτρου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:34</a>, expressão não encontrada em outro lugar do grego, deve significar em seu contexto não a partir de uma medida, sem (utilizar) medida (o oposto é <span class=\"greek\">ἐν</span> <span class=\"greek\">μέτρῳ</span> Ezk 4:11, 16; Jdth 7:21).—DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέτωπον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέτωπον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hom.+), fronte, testa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:48</a> D. De uma jovem: velada <span class=\"greek\">ἕως</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μ</span>. Hv 4, 2, 1. Como lugar assinalado por algum sinal (ver BStade, D. Kainszeichen: ZAW 14, 1894, 250ff; PsSol 15:9; Diphilus Com. [IV a.C.], Fgm. 66, 8 K.; Herodas 5, 79; Lucian, Pisc. 46; Porphyr., Vi. Pyth. 15; Liban., Or. 25, 21 vol. II p. 547, 1 F.; de escravo marcado, Martial 3, 21) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:3</a>; 9:4; 13:16; 14:1, 9; 17:5; 20:4; 22:4 (SIG 1168, 48 e 54 [letras]; PLille 29 II, 36; Ezk 9:4 e outros).—B. 218. DELG 1 <span class=\"greek\">μ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέχρι</h1><div class=\"entry-meta\"><span>preposição e conjunção</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέχρι</span>, até mesmo diante de vogais, como no ático <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:16</a>; Job 32:12. Em três passagens do NT (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:30</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:19</a> <span class=\"greek\">μέχρις</span> <span class=\"greek\">οὗ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:4</a> <span class=\"greek\">μέχρις</span> <span class=\"greek\">αἵματος</span>), bem como Hv 4, 1, 9 (<span class=\"greek\">μέχρις</span> <span class=\"greek\">ὅτε</span>), Hs 9, 11, 1 (<span class=\"greek\">μέχρις</span> <span class=\"greek\">ὀψέ</span>), a forma empregada antes de vogal é <span class=\"greek\">μέχρις</span> (Vett. Val. 357, 19; IG XII, 5, 647; SIG 888, 150 [antes de consoante]; 958, 16; 1109, 41; Threatte II 669–71; papiros [Mayser p. 244]. Sobre a LXX, ver Thackeray p. 136.—B-D-F §21; Mlt-H. 113; 331), em geral, “até”; em nossa literatura como preposição com genitivo (Hom.+) e como conjunção (Thu., Pla. e outros).</p><p class=\"entry-text\">① Indicador de extensão até um ponto no espaço, até, com genitivo: <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> GPt 10:40. <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἀσίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:4</a> D. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἰερουσαλὴμ</span>…<span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰλλυρικοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:19</a> (<span class=\"greek\">ἀπὸ</span>…<span class=\"greek\">μ</span>. como SIG 973, 6f). <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἔσω</span> <span class=\"greek\">φλεβῶν</span> MPol 2:2 (Jos., Bell. 6, 304 <span class=\"greek\">μ</span>. <span class=\"greek\">ὀστέων</span>).</p><p class=\"entry-text\">② Indicador de continuidade temporal até determinado ponto, até.</p><p class=\"entry-text\">ⓐ Como preposição com genitivo: <span class=\"greek\">μ</span>. (<span class=\"greek\">τῆς</span>) <span class=\"greek\">νῦν</span> IMg 8:1; Papias (3:3) (Chion, Ep. 16, 4; Longus 4, 16, 2; Xenophon Eph. 1, 4, 1; Jos., Ant. 7, 386; 17, 114; Just., D. 82, 1 e 3 e outros; cf. <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">Χ</span>., Cyr. 7, 3, 15; PTebt 50, 26 [112/11 a.C.]; BGU 256, 9; Just., D. 78, 8). <span class=\"greek\">μ</span>. <span class=\"greek\">ὀψέ</span> Hs 9, 11, 1. <span class=\"greek\">μέχρι</span> <span class=\"greek\">τίνος</span>; por quanto tempo? (Just., A I, 32, 2; Alciphron 4, 17, 2; Achilles Tat. 2, 5, 1) v 3, 10, 9. <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σήμερον</span>, até hoje (Jos., Ant. 9, 28) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:23</a>; cf. 28:15; Hv 2, 2, 4. <span class=\"greek\">μ</span>. <span class=\"greek\">μεσονυκτίου</span>, até meia-noite <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:7</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">Ἰωάννου</span>, até (o tempo de) João <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:16</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπιφανείας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:14</a> (Just., D. 120, 3 <span class=\"greek\">μ</span>.…<span class=\"greek\">τῆς</span> <span class=\"greek\">παρουσίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>). <span class=\"greek\">μ</span>. <span class=\"greek\">καιροῦ</span> <span class=\"greek\">διορθώσεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:10</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θερισμοῦ</span> (por <span class=\"greek\">ἕως</span>; outra variante de leitura <span class=\"greek\">ἄχρι</span>), até o tempo da colheita <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:30</a>, variante de leitura. <span class=\"greek\">μ</span>. <span class=\"greek\">τέλους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:6</a>, variante de leitura; 14 (cf. Ar. [Milne 76, 47f] <span class=\"greek\">μ</span>. <span class=\"greek\">τελειώσεως</span> <span class=\"greek\">χρόνων</span>).—<span class=\"greek\">ἀπό</span>…<span class=\"greek\">μ</span>. (POxy 1647, 20 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἀνατολῆς</span> <span class=\"greek\">ἡλίου</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">δύσεως</span>; EpArist 298): <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τετάρτης</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ταύτης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὥρας</span>, do quarto dia até esta hora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:30</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἀδὰμ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">Μωϋσέως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:14</a> (cf. Just., D. 92, 2 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">Μωϋσέως</span>).</p><p class=\"entry-text\">ⓑ Como conjunção, até (B-D-F §383, 2; Rob. 975): <span class=\"greek\">μ</span>. <span class=\"greek\">καταντήσωμεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:13</a> (cf. Hdt. 4, 119, 4; SIG 976, 71 <span class=\"greek\">μέχρι</span> <span class=\"greek\">ποιήσωσιν</span>; PCairPreis 48, 7 <span class=\"greek\">μέχρι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοιαρίδιον</span> <span class=\"greek\">εὑρῶμεν</span>; TestSol 9:8 P; SibOr 3, 570. Sobre a omissão de <span class=\"greek\">ἄν</span>, ver Mlt. 168f; Rydbeck, 144–53). <span class=\"greek\">μ</span>. <span class=\"greek\">οὗ</span> com subjuntivo (Herodas 2, 43; 8, 8 [Cunningham lê <span class=\"greek\">μέχρις</span> <span class=\"greek\">εὖ</span> em ambos]; POxy 293, 7 [27 d.C.] <span class=\"greek\">μέχρι</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἀποστείλῃς</span> Da 11:36 Theod.; EpArist 298) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:30</a> (<span class=\"greek\">μ</span>. <span class=\"greek\">ὅτου</span>, variante de leitura); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:19</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ὅτε</span> (<span class=\"greek\">ὅτου</span>, variante de leitura) Hv 4, 1, 9; GJs 10:2 (ver B-D-F §455, 3).</p><p class=\"entry-text\">③ Indicador de grau ou medida, até o ponto de, com genitivo (Appian, Bell. Civ. 3, 69 §284 <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">τέλους</span> = até o fim; Jos., Ant. 11, 81 <span class=\"greek\">μ</span>. <span class=\"greek\">θρήνων</span>; Ath. 12:3 <span class=\"greek\">μ</span>. <span class=\"greek\">τοσούτου</span>): <span class=\"greek\">κακοπαθεῖν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">δεσμῶν</span>, sofrer a ponto de ser aprisionado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:9</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">αἵματος</span> <span class=\"greek\">ἀντικαταστῆναι</span>, resistir a ponto de derramar o próprio sangue ao ser ferido ou morto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:4</a> (<span class=\"greek\">μ</span>. <span class=\"greek\">αἵμ</span>. como Herodian 2, 6, 14). <span class=\"greek\">μ</span>. <span class=\"greek\">θανάτου</span> <span class=\"greek\">διωχθῆναι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">δουλείας</span> <span class=\"greek\">εἰσελθεῖν</span> 1 Cl 4:9 (cf. 2 Macc 13:14; Jos., Bell. 2, 141). De Cristo: <span class=\"greek\">ὑπήκοος</span> <span class=\"greek\">μ</span>. <span class=\"greek\">θανάτου</span>, obediente até a morte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:8</a> (cf. PTor I, 1 VII, 28 [116 a.C.] <span class=\"greek\">μ</span>. <span class=\"greek\">τελευτῆς</span> <span class=\"greek\">βιοῦ</span>). De Epafrodito: <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">θανάτου</span> <span class=\"greek\">ἤγγισεν</span>, versículo 30 (<span class=\"greek\">μέχρι</span> <span class=\"greek\">θανάτου</span> para indicar grau: Diod S 15, 27, 2; Cebes 26, 3; Appian, Bell. Civ. 2, 113 §471; 3, 77 §314; 3, 90 §372; 4, 135 §570 e outros; Polyaenus 7, 30; 8, 49; Just., D. 11, 4 e outros; schol. sobre Apollon. Rhod. 3, 427–31a; 2 Macc 13:14).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μή</h1><div class=\"entry-meta\"><span>partícula negativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μή</span> (Hom.+), partícula negativa, “não”: “<span class=\"greek\">μή</span> é a negação da vontade, do desejo, da dúvida. Se <span class=\"greek\">οὐ</span> nega o fato, <span class=\"greek\">μή</span> nega a ideia” (Rob. 1167). No grego koiné do NT, o uso simplificou-se a tal ponto que <span class=\"greek\">οὐ</span> é geralmente a negação empregada com o indicativo, e <span class=\"greek\">μή</span> com os demais modos (B-D-F §426; Rob. 1167).</p><p class=\"entry-text\">① Indicador de negação, não.</p><p class=\"entry-text\">ⓐ Em orações negativas.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Em orações condicionais depois de <span class=\"greek\">ἐάν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:20</a>; 6:15; 10:13; 12:29; 18:3, 16, 35; 26:42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:27</a>; 7:3f; 10:30; 12:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:3</a>, 5; J 3:2f, 5, 27 e outros. Depois de <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἄν</span> (=<span class=\"greek\">ἐάν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:14</a>; 11:6; 19:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:11</a>; 10:15; 11:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:18</a>; 18:17. Depois de <span class=\"greek\">ὅσοι</span> <span class=\"greek\">ἄν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:15</a>. Depois de <span class=\"greek\">ὅστις</span> <span class=\"greek\">ἄν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:23</a>. Depois de <span class=\"greek\">εἰ</span> numa condição simples (B-D-F §428, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:3</a>. Depois de <span class=\"greek\">εἰ</span> numa condição contrária ao fato (B-D-F §428, 2; Rob. 1169) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:33</a>; 15:22, 24; 18:30; 19:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:7</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">μή</span>, se não, exceto (que); <span class=\"greek\">εἰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μήγε</span>, caso contrário, com verbo e elipticamente (B-D-F §428, 3; 439, 1; Rob. 1024f; cf. POxy 1185, 30) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:13</a>; 6:1; 9:17; 11:27; 12:4, 24 e muito frequentemente (GHarder, 1 Cor 7:17: TLZ 79, ’54, 367–72).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Em orações finais: <span class=\"greek\">ἵνα</span> <span class=\"greek\">μή</span>, a fim de que ... não Mt 5:29f; 7:1; 17:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:9</a>; 4:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:10</a>, 12; 16:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:20</a>; 7:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:25</a> (Ps 15:8); 4:17; 24:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:25</a>; 15:20 e outros. <span class=\"greek\">ὅπως</span> <span class=\"greek\">μή</span>, a fim de que ... não <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:29</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">ἵνα</span> IRo 3:2. Sobre o infinitivo com negação como perífrase para orações finais, ver abaixo.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Em orações consecutivas: <span class=\"greek\">ὥστε</span> <span class=\"greek\">μή</span> seguido de infinitivo (cf. PHib 66, 5), de sorte que não <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:8</a>; seguido de imperativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:5</a>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. Em orações interrogativas com elemento de dúvida: <span class=\"greek\">δῶμεν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δῶμεν</span>; devemos pagar (a eles) ou não? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:14</a>.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. Em algumas orações relativas (B-D-F §428, 4; Mlt. 171; 239f): <span class=\"greek\">διδάσκοντες</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:11</a> (cf. Lucian, Dial. Deor. 13, 1; PGM 4, 2653 <span class=\"greek\">ὸ̔</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">θέμις</span> <span class=\"greek\">γενέσθαι</span>; CPR I, 19, 17; 2 Macc 12:14; Sir 13:24). Da língua literária provém <span class=\"greek\">ᾧ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πάρεστιν</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">τυφλός</span> <span class=\"greek\">ἐστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:9</a>, cuja oração relativa tem sentido hipotético. <span class=\"greek\">ὅσα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">θέλετε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:29</a> D. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:18</a>, variante de leitura. Sobre <span class=\"greek\">ὸ̔</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὁμολογεῖ</span> (variante <span class=\"greek\">ὸ̔</span> <span class=\"greek\">λύει</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:3</a>, ver ARahlfs, TLZ 40, 1915, 525.</p><p class=\"entry-text\"><span class=\"greek\">ζ</span>. Numa oração causal, contrariamente à regra que exige <span class=\"greek\">οὐ</span>: <span class=\"greek\">ὅτι</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πεπίστευκεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:18</a> (cf. Epict. 4, 4, 8; Jos., C. Ap. 1, 217 <span class=\"greek\">διήμαρτον</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἱεραῖς</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">βίβλοις</span> <span class=\"greek\">ἐνέτυχον</span>; Ps.-Clem., Hom. 8, 4; 11, 8; 32; Ath. 14, 2 <span class=\"greek\">ὅτι</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κοινῶς</span> <span class=\"greek\">ἐκείνοις</span> <span class=\"greek\">θεοσεβοῦμεν</span>; Dio Chrys. 31, 94; 110.—B-D-F §428, 5; Mlt. 171; 239; Mlt-Turner 284; Rahlfs, loc. cit.).</p><p class=\"entry-text\">ⓑ Com diferentes modos verbais.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com infinitivo (B-D-F §399, 3; 400, 4; 5; Mlt-Turner 285f).</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">א</span>. Depois de verbos que exprimem conceito negativo, geralmente omitido na tradução: <span class=\"greek\">ἀντιλέγοντες</span> <span class=\"greek\">ἀνάστασιν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἶναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:27</a> (variante de leitura <span class=\"greek\">λέγοντες</span>). <span class=\"greek\">ἀπαρνεῖσθαι</span> 22:34. <span class=\"greek\">παραιτεῖσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:19</a>. <span class=\"greek\">ἐγκόπτειν</span> <span class=\"greek\">τινά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:7</a>. <span class=\"greek\">προσέχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:1</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">δύναμαι</span> <span class=\"greek\">μὴ</span>, não posso fazer outra coisa senão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:20</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ב</span>. Em geral, após verbos de dizer, informar, ordenar, julgar etc.—Em orações declarativas: depois de <span class=\"greek\">ἀποκρίνεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:7</a>. <span class=\"greek\">λέγειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:27</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:8</a>; AcPlCor 2:19. <span class=\"greek\">ὀμνύναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:18</a>. <span class=\"greek\">θέλειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:3</a>. <span class=\"greek\">χρηματίζεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:26</a>.—Em orações que denotam convocação ou exortação: depois de <span class=\"greek\">λέγειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:34</a>, 39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:22</a>; 12:3. <span class=\"greek\">γράφειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:9</a>, 11. <span class=\"greek\">κηρύσσειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:21</a>. <span class=\"greek\">παραγγέλλειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:4</a>; 4:18; 5:28, 40; 1 Cor 7:10f (com acusativo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:3</a>; 6:17. <span class=\"greek\">αἰτεῖσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:13</a>. <span class=\"greek\">εὔχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:7</a> (com acusativo). <span class=\"greek\">χρηματίζεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:12</a>. <span class=\"greek\">ἀξιοῦν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:38</a>. <span class=\"greek\">βοᾶν</span> 25:24.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ג</span>. Depois de predicados que contêm julgamento sobre o que é expresso pelo infinitivo (com ou sem artigo; cf. Just., D. 68, 8 <span class=\"greek\">ταῦτα</span> <span class=\"greek\">τολμῶσι</span> <span class=\"greek\">λέγειν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">γεγράφθαι</span>): <span class=\"greek\">καλόν</span> (subentendido <span class=\"greek\">ἐστιν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:1</a> (ApcEsdr 1, 6, 21); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:18</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:21</a>. <span class=\"greek\">ἄλογον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:27</a> (com acusativo). <span class=\"greek\">κρεῖττον</span> <span class=\"greek\">ἦν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:21</a>. <span class=\"greek\">αἱρετώτερον</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γεννηθῆναι</span> Hv 4, 2, 6. Cf. <span class=\"greek\">δεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:21</a> (cf. uso com <span class=\"greek\">ἐχρῆν</span> TestJob 37:6).</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ד</span>. Com genitivo do infinitivo substantivado: <span class=\"greek\">τοῦ</span> <span class=\"greek\">μή</span>, para que não (latim ne): depois de verbos que exprimem impedimento <span class=\"greek\">κατέχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:42</a>. <span class=\"greek\">παύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:10</a> (Ps 33:14). <span class=\"greek\">καταπαύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:18</a>. <span class=\"greek\">κωλύειν</span> 10:47. <span class=\"greek\">κρατεῖσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:16</a>; cf. <span class=\"greek\">ἀνένδεκτόν</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τοῦ</span>…<span class=\"greek\">μὴ</span> <span class=\"greek\">ἐλθεῖν</span> 17:1.—Também depois de outras expressões: <span class=\"greek\">ὀφθαλμοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">βλέπειν</span>, <span class=\"greek\">ὦτα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀκούειν</span>, olhos que não devem ver, ouvidos que não devem ouvir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:8</a>, 10 (Ps 68:24). Em lugar de uma oração consecutiva: <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">μοιχαλίδα</span>, para que ela não cometa adultério, se ... 7:3.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ה</span>. Com infinitivo substantivado após preposições: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μή</span>, de modo que ... não; para que ... não <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:4</a>. Seguido de acusativo e infinitivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:7</a>.—<span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μή</span>, porque ... não (PPetr II, 11, 1, 7 [III a.C.] <span class=\"greek\">τοῦτο</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">γίνεται</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀθροῦν</span> <span class=\"greek\">ἡμᾶς</span>; 2 Macc 2:11; ApcMos 42 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γινώσκειν</span>; Just., D. 95, 1 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">φυλάξαι</span>; Tat. 2, 1 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">βούλεσθαι</span>) Mt 13:5f; Mk 4:5f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:2</a> (com acusativo).—<span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span>, para que ... não (Ptolem. Pap. aus Alexandria 4, 3 em Witkowski p. 51 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">βασιλεῖ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χρήσιμον</span>; Esth 3:13d, e; Bar 1:19; 2:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:8</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ו</span>. Com dativo do infinitivo substantivado: <span class=\"greek\">τῷ</span> <span class=\"greek\">μή</span>, porque ... não <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:13</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ז</span>. Com nominativo ou acusativo do infinitivo substantivado (2 Esdr 6:8; ver B-D-F §399, 3; ver Rob. 1038) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:1</a>; 10:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:6</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Muito frequentemente com particípio, conforme a tendência do grego posterior de preferir <span class=\"greek\">μή</span> a <span class=\"greek\">οὐ</span>; exceções em B-D-F §430; ver Rob. 1172.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">א</span>. <span class=\"greek\">μή</span> é regularmente empregado para negar o particípio com artigo, quando esse particípio tem sentido hipotético ou se refere a nenhuma pessoa determinada e possui significado geral (Artem. 4, 22 p. 215, 14 <span class=\"greek\">οἱ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">νοσοῦντες</span>; ParJer 6:24 <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀκούων</span>; Just., A I, 4, 2 <span class=\"greek\">τοὺς</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐλεγχομένους</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἐμοῦ</span>, todo aquele que não está comigo Mt 12:30ab; Lk 11:23ab; <span class=\"greek\">ὁ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πιστεύων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:18</a>. <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μή</span> ... <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:26</a>; 1J 3:10ab; 2J 9. <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:12</a>. <span class=\"greek\">μακάριοι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:29</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:22</a>. <span class=\"greek\">τῶν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δυναμένων</span> <span class=\"greek\">ἀποκτεῖναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:28b</a> e frequentemente.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ב</span>. Com particípio de sentido condicional, causal ou concessivo: <span class=\"greek\">πᾶν</span> <span class=\"greek\">δένδρον</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ποιοῦν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:10</a>; 7:19. Cf. 9:36; 13:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:24</a>. <span class=\"greek\">θερίσομεν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐκλυόμενοι</span>, ceifaremos, se não desfalecermos (antes da colheita) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:9</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">ὄντος</span> <span class=\"greek\">νόμου</span>, quando não há lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:13</a>. <span class=\"greek\">νόμον</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχοντες</span>, embora não tenham lei 2:14. <span class=\"greek\">μὴ</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">νόμον</span>, embora eu próprio não esteja sob a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:20</a> (cf. TestAbr B 11 p. 115, 22 [Stone p. 78] <span class=\"greek\">μὴ</span> <span class=\"greek\">ἰδὼν</span> <span class=\"greek\">θάνατον</span>). <span class=\"greek\">μὴ</span> <span class=\"greek\">μεμαθηκώς</span>, sem ter aprendido (essas coisas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:15</a> (cf. TestAbr B 2 p. 106, 1 [Stone p. 60] <span class=\"greek\">μὴ</span> <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστιν</span>; TestJob 11:7 <span class=\"greek\">μὴ</span> <span class=\"greek\">λαμβάνων</span>…<span class=\"greek\">ἐνέχυρα</span>; Just., A I, 5, 1 <span class=\"greek\">μὴ</span> <span class=\"greek\">φροντίζοντες</span>, D. 110, 2 <span class=\"greek\">μὴ</span> <span class=\"greek\">συνιέντες</span>). <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχοντος</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἀποδοῦναι</span>, mas, visto que ele não podia pagar de volta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:25</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">βουλόμενος</span>, visto que (Deus) não quis AcPlCor 2:12 (cf. TestAbrB 5 p. 109, 24f [Stone p. 66] <span class=\"greek\">μὴ</span> <span class=\"greek\">θέλων</span>…<span class=\"greek\">παρακοῦσαι</span>).</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ג</span>. Quando se pretende indicar que a afirmação possui validade subjetiva (Just., D. 115, 3 <span class=\"greek\">ὡς</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γεγενημένου</span> <span class=\"greek\">ἱερέως</span>): <span class=\"greek\">ὡς</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">λαβών</span>, como se não tivesses recebido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:7</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐρχομένου</span> <span class=\"greek\">μου</span>, versículo 18.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ד</span>. Mas também muito frequentemente onde o grego mais antigo exigiria <span class=\"greek\">οὐ</span> (sobre a evolução, ver Schwyzer II 595f; B-D-F §430, 3; Burton §485 [464 Z.]; cf. <span class=\"greek\">οὐ</span> 2b; quanto a <span class=\"greek\">μή</span> aqui, cf. Just., A I, 3, 9, 3 <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">δεκαδύο</span>…<span class=\"greek\">λαλεῖν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δυνάμενοι</span>; D. 85, 4 <span class=\"greek\">διὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">μὴ</span>…<span class=\"greek\">συνόντας</span> <span class=\"greek\">ἡμῖν</span>; Mel., P. 71, 518f): <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὄντα</span>, o que não existe (na realidade, e não apenas na opinião de Paulo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:28</a> (Philo, Op. M. 81 <span class=\"greek\">τὸ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὄντα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">παραγαγεῖν</span>; Ath. 4:2 <span class=\"greek\">τὸ</span> <span class=\"greek\">ὸ̓ν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">γίνεται</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὄν</span>); Hv 1, 1, 6. <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">βλεπόμενα</span>, coisas invisíveis 2 Cor 4:18ab. <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δέοντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:13</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">καθήκοντα</span> (3 Macc 4:16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:28</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">σαλευόμενα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:27</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γνόντα</span> <span class=\"greek\">ἁμαρτίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:21</a>. <span class=\"greek\">τυφλὸς</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">βλέπων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:11</a>. Ver também <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀσθενήσας</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">κατενόησεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:19</a>, em que, como muitas vezes, a ideia principal é expressa pelo particípio.</p><p class=\"entry-text\">ⓒ Em sentido proibitivo, em orações independentes, para exprimir desejo negativo ou advertência.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com subjuntivo: não façamos, não devemos: subjuntivo presente <span class=\"greek\">μὴ</span> <span class=\"greek\">γινώμεθα</span> <span class=\"greek\">κενόδοξοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:26</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐγκακῶμεν</span> 6:9. <span class=\"greek\">μὴ</span> <span class=\"greek\">καθεύδωμεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:6</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:8</a>. Com subjuntivo aoristo <span class=\"greek\">μὴ</span> <span class=\"greek\">σχίσωμεν</span> <span class=\"greek\">αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:24</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com optativo (B-D-F §427, 4; Rob. 1170) <span class=\"greek\">μὴ</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">λογισθείη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:16</a> (cf. Job 27:5). <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γένοιτο</span> <span class=\"greek\">καυχᾶσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:14</a> (cf. 1 Macc 9:10; 13:5). Especialmente na fórmula <span class=\"greek\">μὴ</span> <span class=\"greek\">γένοιτο</span> (ver <span class=\"greek\">γίνομαι</span> 4a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:4</a>, 31; 6:2, 15; 7:7, 13; 9:14; 11:1, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:17</a>; 3:21.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Com imperativo presente.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">א</span>. Para expressar ordem de validade geral (TestReub 2:10) <span class=\"greek\">μὴ</span> <span class=\"greek\">γίνεσθε</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὑποκριταί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:16</a>; cf. versículo 19. <span class=\"greek\">μὴ</span> <span class=\"greek\">μεριμνᾶτε</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span> <span class=\"greek\">ὑμῶν</span>, versículo 25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:22</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:1</a>; 10:31; 19:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:30</a>; 10:4, 7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:9</a>; 7:5, 12f, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:26</a> (Ps 4:5), 29 e frequentemente.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ב</span>. Para pôr fim a uma condição já existente (Aeschyl., Sept. 1036; Chariton 2, 7, 5 <span class=\"greek\">μὴ</span> <span class=\"greek\">ὀργίζου</span> = “não continues irado”; PHib 56, 7 [249 a.C.]; PAmh 37, 7; POxy 295, 5; Wsd 1:12 e outros lugares da LXX; TestAbr B 9 p. 113, 20 [Stone p. 74]; JosAs 14:11; GrBar 7:6 e ApcMos 16 <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβοῦ</span>; Just., D. 87, 1 <span class=\"greek\">μὴ</span>…<span class=\"greek\">λοιπὸν</span> <span class=\"greek\">ὑπολάμβανε</span>; Mlt. 122ff) <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβεῖσθε</span>, não tenhais (mais) medo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:27</a>; 17:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:10</a>; cf. 1:13, 30. <span class=\"greek\">μὴ</span> <span class=\"greek\">κλαῖε</span>, não chores (mais) 7:13; cf. 23:28 (GrBar16:1) <span class=\"greek\">μὴ</span> <span class=\"greek\">σκύλλου</span>, não te incomodes (mais) 7:6; cf. 8:49, variante de leitura (TestAbr B 2 p. 107, 2 [Stone p. 62] <span class=\"greek\">μὴ</span> <span class=\"greek\">σκύλλε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">παιδάριον</span>).—9:50; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:16</a>; 6:43. <span class=\"greek\">μὴ</span> <span class=\"greek\">γράφε</span>, não escrevas (mais) = que isso não continue escrito 19:21. <span class=\"greek\">μή</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἅπτου</span>, não te agarres (mais) a mim = solta-me 20:17. <span class=\"greek\">μὴ</span> <span class=\"greek\">γίνου</span> <span class=\"greek\">ἄπιστος</span>, versículo 27.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:15</a>; 20:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:18</a>, 20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:1</a> e frequentemente.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. Com imperativo aoristo (Od. 16, 301; Lucian, Paras. <span class=\"greek\">μὴ</span> <span class=\"greek\">δότε</span>; 1 Km 17:32; TestJob 45:1 <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐπιλάθεσθε</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>) <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐπιστρεψάτω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:31b</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">καταβάτω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:31a</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">γνώτω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:3</a>.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. Com subjuntivo aoristo.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">א</span>. Quase sempre para impedir que uma ação proibida se inicie (Plut., Alex. 696 [54, 6] <span class=\"greek\">μὴ</span> <span class=\"greek\">φιλήσῃς</span> = “não beijes”; PPetr II, 40a, 12 [III a.C.]; POxy 744, 11; BGU 380, 19; LXX; TestAbr A 2 p. 79, 8 [Stone p. 6] <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐνέγκωσιν</span> <span class=\"greek\">ἵππους</span>; 16 p. 97, 5 [Stone p. 42] <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐκφοβήσῃς</span> <span class=\"greek\">αὐτόν</span>; TestJob 39:11 <span class=\"greek\">μὴ</span> <span class=\"greek\">κάμητε</span> <span class=\"greek\">εἰκῇ</span>; ParJer 3:5 <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀπολέσητε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>; ApcEsdr 7:11 <span class=\"greek\">μὴ</span> <span class=\"greek\">μνησθῇς</span>; Just., D. 137, 1 <span class=\"greek\">μὴ</span> <span class=\"greek\">κακόν</span> <span class=\"greek\">τι</span> <span class=\"greek\">εἴπητε</span>.—Este é o sentido de <span class=\"greek\">μὴ</span> <span class=\"greek\">θαυμάσῃς</span> Herm. Wr. 11, 17; ver <span class=\"hebrew\" dir=\"rtl\">ב</span> abaixo) <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβηθῇς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a>; 10:26 (JosAs 23:15; cf. TestJob 17:6 <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβηθῆτε</span> <span class=\"greek\">ὅλως</span>). <span class=\"greek\">μὴ</span> <span class=\"greek\">δόξητε</span> 3:9; cf. 5:17. <span class=\"greek\">μὴ</span> <span class=\"greek\">ἅψῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:21</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀποστραφῇς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:42</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">κτήσησθε</span> 10:9 e frequentemente. Também com terceira pessoa do subjuntivo aoristo: <span class=\"greek\">μή</span> <span class=\"greek\">τις</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐξουθενήσῃ</span>, ninguém deve desprezá-lo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:11</a>. <span class=\"greek\">μή</span> <span class=\"greek\">τίς</span> <span class=\"greek\">με</span> <span class=\"greek\">δόξῃ</span> <span class=\"greek\">εἶναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:16</a>. <span class=\"greek\">μή</span> <span class=\"greek\">τις</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἐξαπατήσῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:3</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">σκληρύνητε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:8</a>, 15 (citação de Ps 94:8) dificilmente é subjuntivo presente; deve antes ser considerado aoristo.</p><p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ב</span>. Só raramente para pôr fim a uma condição já existente (normalmente emprega-se para isso o imperativo presente; ver acima 1 c<span class=\"greek\">γ</span><span class=\"hebrew\" dir=\"rtl\">ב</span>) (TestAbr B 7 p. 111, 19 [Stone p. 70] <span class=\"greek\">μὴ</span> <span class=\"greek\">κλαύσῃς</span>, não chores mais) <span class=\"greek\">μὴ</span> <span class=\"greek\">θαυμάσῃς</span>, já não precisas admirar-te <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:7</a> (“não precisas surpreender-te”: ver Mlt. 124; 126; e ver <span class=\"hebrew\" dir=\"rtl\">א</span> acima).</p><p class=\"entry-text\"><span class=\"greek\">ζ</span>. Em expressões abruptas sem verbo (ParJer 1:7 <span class=\"greek\">μὴ</span> <span class=\"greek\">κύριέ</span> <span class=\"greek\">μου</span>): <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἑορτῇ</span>, (não devemos) (agir contra ele) durante a festa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:2</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:40</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> (<span class=\"greek\">ποιήσωμεν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:8</a> (B-D-F §427, 4). <span class=\"greek\">μὴ</span> <span class=\"greek\">ὀκνηροὶ</span> (<span class=\"greek\">γίνεσθε</span>) 12:11. Cf. 14:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:6</a> e outros (B-D-F §481).</p><p class=\"entry-text\">② Indicador de conjunção.</p><p class=\"entry-text\">ⓐ Depois de verbos de temer etc.: que ... (não), para que não, por receio de que, B-D-F §370.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com subjuntivo presente (3 Macc 2:23) <span class=\"greek\">ἐπισκοποῦντες</span>…<span class=\"greek\">μή</span> <span class=\"greek\">τις</span> <span class=\"greek\">ῥίζα</span>…<span class=\"greek\">ἐνοχλῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:15</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com subjuntivo aoristo (Pla., Apol. 1, 17a) <span class=\"greek\">φοβηθεὶς</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">διασπασθῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:10</a>. Também após um presente 27:17 (cf. Tob 6:15). Depois de <span class=\"greek\">βλέπειν</span> no sentido de tomar cuidado (PLond III, 964, 9 p. 212 [II/III d.C.] <span class=\"greek\">βλέπε</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐπιλάθῃ</span> <span class=\"greek\">μηδέν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:25</a>. <span class=\"greek\">σκοπῶν</span> <span class=\"greek\">σεαυτὸν</span>, <span class=\"greek\">μὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">πειρασθῇς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:1</a>. <span class=\"greek\">στελλόμενοι</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">μή</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἡμάς</span> <span class=\"greek\">μωμήσηται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:20</a>. <span class=\"greek\">ὁρᾶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:15</a>. Elipticamente, como numa aposiopese: <span class=\"greek\">ὅρα</span> <span class=\"greek\">μή</span>, cuidado! não faças isso! <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:10</a>; 22:9 (B-D-F §480, 5; Rob. 932; 1203).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Com futuro do indicativo, em vez do subjuntivo que se esperaria (X., Cyr. 4, 1, 18 <span class=\"greek\">ὅρα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">ἑκάστῳ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">δεήσει</span>): <span class=\"greek\">βλέπετε</span> <span class=\"greek\">μή</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἔσται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:8</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:12</a>.</p><p class=\"entry-text\">ⓑ No lugar de uma oração final = para que ... não: com subjuntivo aoristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:6</a>.</p><p class=\"entry-text\">③ Indicador de expectativa de resposta negativa a uma pergunta (B-D-F §427, 2; 4; 440; Rob. 1168; 1175; Mlt-Turner 283).</p><p class=\"entry-text\">ⓐ Em perguntas diretas (X. Eph. 398, 26 H.; Job 1:9; 8:11; TestAbr A 2 p. 79, 9f [Stone p. 6]; B 6 p. 110, 6 [Stone p. 68]; TestJob 15, 6; 27, 1; ApcSed 7:2; ApcMos 8:27), mais ou menos “não é verdade, pois não, que ...?”, com expectativa de resposta negativa; na tradução, a negação pode ser expressa de várias maneiras, de forma a sugerir que uma resposta inconveniente seria recebida com profundo espanto, por exemplo: <span class=\"greek\">μή</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ὑστερήσατε</span>; não vos faltou nada, faltou? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:35</a>; <span class=\"greek\">μὴ</span> <span class=\"greek\">λίθον</span> <span class=\"greek\">ἐπιδώσει</span> <span class=\"greek\">αὐτῷ</span>; dar-lhe-ia alguém uma pedra? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:9</a>; de modo semelhante, versículo 10; 9:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:34</a>; 11:11, variante de leitura; 17:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:4</a>; 4:12, 33; 6:67; 7:35, 51f; 21:5 (cf. <span class=\"greek\">μήτι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:28</a> (Ex 2:14), 42 (Am 5:25); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:3</a>, 5 (cf. Job 8:3); 9:14, 20 (Is 29:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:13</a>; 9:8f; 10:22 e outros. <span class=\"greek\">μὴ</span> <span class=\"greek\">γάρ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:22</a>.—Em casos como Ro 10:18f; 1 Cor 9:4f, <span class=\"greek\">μή</span> é palavra interrogativa e <span class=\"greek\">οὐ</span> nega o verbo. A dupla negação leva a esperar uma resposta afirmativa (B-D-F §427, 2; ver Rob. 1173f; Tetrast. Iamb. 17, 2 p. 266 <span class=\"greek\">μὴ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστι</span> <span class=\"greek\">χλόη</span>; = “há grama, não há?”).</p><p class=\"entry-text\">ⓑ Em perguntas indiretas, se ... não <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:35</a> (cf. Epict. 4, 5, 18a; Arrian, Anab. 4, 20, 2 <span class=\"greek\">μή</span> <span class=\"greek\">τι</span> <span class=\"greek\">βίαιον</span> <span class=\"greek\">ξυνέβη</span> = se ocorreu algo violento [espera-se que não]; Jos., Ant. 6, 115).</p><p class=\"entry-text\">④ Indicador de negação reforçada: combinado com <span class=\"greek\">οὐ</span>, <span class=\"greek\">μή</span> tem o efeito de intensificar a negação (Kühner-G. II 221–23; Schwyzer II 317; Mlt. 187–92 [tratamento minucioso do uso no NT]; B-D-F §365; RLudwig: D. prophet. Wort 31 ’37, 272–79; JLee, NovT 27, ’85, 18–23; B-D-F §365.—Pla., Hdt. e outros [Kühner-G. loc. cit.]; SIG 1042, 16; POxy 119, 5, 14f; 903, 16; PGM 5, 279; 13, 321; LXX; TestAbr A 8 p. 85, 11 [Stone p. 46]; JosAs 20:3; GrBar 1:7; ApcEsdr 2:7; Just., D. 141, 2). <span class=\"greek\">οὐ</span> <span class=\"greek\">μή</span> é a maneira mais categórica de negar algo no futuro.</p><p class=\"entry-text\">ⓐ Com subjuntivo.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com subjuntivo aoristo (TestAbr A 17 p. 99, 7 <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δυνηθῇς</span> <span class=\"greek\">θεάσασθαι</span>; JosAs 20:3; ParJer 2:5; 8:5; ApcSed 12:5; 13:6; Just., D. 141, 2; Ael. Aristid. 50, 107 K. = 26 p. 533 D.: <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">καταφρονήσωσι</span>; Diogenes, Ep. 38, 5; UPZ 62, 34; 79, 19), nunca, certamente não etc. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:18</a>, 20, 26; 24:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:15</a>; 6:37ab; 10:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.52\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:52</a>; 10:28; 11:26; 13:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:12</a> (Jer 38:34); 13:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:6</a> (Is 28:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:11</a>; 3:12; 18:21–23 e outros.—Também numa pergunta retórica, quando se espera resposta afirmativa: <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ποιήσῃ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκδίκησιν</span>; não fará ele justiça? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:7</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πίω</span> <span class=\"greek\">αὐτό</span>; não hei de bebê-lo? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:11</a>. <span class=\"greek\">τίς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβηθῇ</span>; quem não temerá? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:4</a>.—Em orações relativas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:41</a> (Hab 1:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:8</a> (Ps 31:2); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:30</a>.—Em orações declarativas e interrogativas após <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:16</a> (<span class=\"greek\">οὐκέτι</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μή</span>, variante de leitura); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.56\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:56</a>; sem <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:35</a>.—Combinado com <span class=\"greek\">οὐδέ</span>: <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γένηται</span> (Mitt-Wilck. I/2, 122, 4 [6 d.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:21</a> (B-D-F §431, 3).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com subjuntivo presente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:5</a>, variante de leitura <span class=\"greek\">ἐγκαταλείπω</span> (adotada por Tdf., enquanto a maioria das edições lê <span class=\"greek\">ἐγκαταλίπω</span>).</p><p class=\"entry-text\">ⓑ Com futuro do indicativo (En 98:12; 99:10; TestAbr A 8 p. 85, 11 [Stone p. 20] <span class=\"greek\">οὐ</span> <span class=\"greek\">μή</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ἀκολουθήσω</span>; GrBar 1:7 <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">προσθήσω</span>; ApcEsdr 2:7 <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">παύσομαι</span>) <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔσται</span> <span class=\"greek\">σοι</span> <span class=\"greek\">τοῦτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:22</a>.—Hm 9:5; Hs 1:5; 4:7. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:6</a>; 26:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:19</a>, variante de leitura; 21:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:14</a>; 6:35b; 10:5 (<span class=\"greek\">ἀκολουθήσωσιν</span>, variante de leitura); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:17</a>. <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εὑρήσουσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:14</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κληρονομήσει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:30</a> (Gen 21:10, variante de leitura); mas a tradição oscila em geral entre futuro e subjuntivo aoristo (ver Mlt. e B-D-F loc. cit.).—DELG. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήγε</h1><div class=\"entry-meta\"><span>partícula composta</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήγε</span>, na fórmula <span class=\"greek\">εἰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μήγε</span>, de outro modo, caso contrário: ver <span class=\"greek\">γέ</span> b<span class=\"greek\">β</span> e <span class=\"greek\">εἰ</span> 6d.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδαμῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηδαμῶς</span> (Aeschyl., Hdt. e outros; papiros [Mayser 182; também POxy 901, 11; PStras 40, 34]; LXX; JosAs; Jos., Ant. 18, 20; 70); também <span class=\"greek\">μηθαμῶς</span> (UPZ 79, 8 [159 a.C.]) 1 Cl 33:1; 45:7; 53:4 (ver B-D-F §33; W-S. §5, 27f; Reinhold §6, 3). De modo algum, certamente não, não; advérbio que expressa reação negativa (Chion, Ep. 16, 7; Lucian, Dial. Deor. 4, 2; Ael. Aristid. 23, 79 K. = 42 p. 794 D.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:14</a>; 11:8; Hv 1, 2, 4; também as passagens de 1 Cl citadas acima.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδέ</h1><div class=\"entry-meta\"><span>partícula disjuntiva negativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηδέ</span>, partícula disjuntiva negativa (Hom.+).</p><p class=\"entry-text\">① E não, mas não, nem, continuando uma negação anterior (quase sempre com <span class=\"greek\">μή</span>).</p><p class=\"entry-text\">ⓐ De tal maneira que as duas negações tenham um único verbo em comum: no particípio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:24</a>; no presente do subjuntivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:18</a>; no imperativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:15</a>. Também pode ocorrer mais de um <span class=\"greek\">μηδέ</span> depois de <span class=\"greek\">μή</span> (Diod S 18, 56, 5 <span class=\"greek\">μὴ</span> <span class=\"greek\">κατιέναι</span> é seguido de <span class=\"greek\">μηδέ</span> cinco vezes com o mesmo verbo) Mt 10:9f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:12</a>.</p><p class=\"entry-text\">ⓑ De tal maneira que <span class=\"greek\">μή</span> e <span class=\"greek\">μηδέ</span> tenham cada qual seu próprio verbo: introduzidos por <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἄν</span> (<span class=\"greek\">ἐάν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:11</a>; por <span class=\"greek\">ἵνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:15</a>; <span class=\"greek\">ὅπως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:26</a>. Ambos os verbos no particípio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:2</a>; no imperativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:27</a>; Ro 6:12f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:5</a> (Pr 3:11). Os imperativos podem ser inteiramente ou parcialmente substituídos por formas equivalentes do subjuntivo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:6</a>; 23:9f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:14</a>. Ambos os verbos no infinitivo (dependentes de <span class=\"greek\">παραγγέλλω</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:4</a>; 6:17; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:21</a>. Mais de um <span class=\"greek\">μηδέ</span> após <span class=\"greek\">μή</span> (Appian, Bell. Civ. 4, 11 §42 <span class=\"greek\">μηδεὶς</span> <span class=\"greek\">μηδένα</span> seguido de <span class=\"greek\">μηδέ</span> três vezes; Just., D. 112, 4 <span class=\"greek\">μηδέποτε</span> e <span class=\"greek\">μηδέ</span> três vezes) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:21</a>; 2 Cl 4:3; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:21</a>; 1 Cor 10:7–10. O primeiro verbo também pode estar ligado a qualquer composto de <span class=\"greek\">μή</span>: <span class=\"greek\">μηδείς</span> (Jos., Ant. 8, 395; Just., A I, 5, 1 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:22</a>. <span class=\"greek\">μήπω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:11</a>.</p><p class=\"entry-text\">ⓒ Na apódose de uma frase condicional: <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">θέλει</span> <span class=\"greek\">ἐργάζεσθαι</span>, <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ἐσθιέτω</span>, quem não quer trabalhar também não deve comer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:10</a>.</p><p class=\"entry-text\">② Nem sequer, nem mesmo (X., Mem. 1, 2, 36; PMagd 28, 4 [218 a.C.]; PTebt 24, 76; Just., A I, 19, 5; Mel., HE 4, 26, 6; Ath 32, 1), precedido de <span class=\"greek\">ὥστε</span> <span class=\"greek\">μή</span> (ou <span class=\"greek\">μηκέτι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:20</a>. <span class=\"greek\">μηδὲ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θύραν</span>, nem sequer o espaço junto à porta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:2</a>. <span class=\"greek\">μηδὲ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κώμην</span> <span class=\"greek\">εἰσέλθῃς</span>, nem sequer entres na aldeia (antes de voltar para casa) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:26</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">τοιούτῳ</span> <span class=\"greek\">μηδὲ</span> <span class=\"greek\">συνεσθίειν</span>, nem mesmo comer com tal pessoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:11</a>. <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ὀνομαζέσθω</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span>, nem sequer se mencione entre vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:3</a>. <span class=\"greek\">μηδὲ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κεφαλῆς</span> <span class=\"greek\">ὄγκον</span>, nem mesmo somente o volume da sua cabeça (inchada) Papias (3:2c).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδείς, μηδεμία, μηδέν</h1><div class=\"entry-meta\"><span>adjetivo e pronome indefinido negativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηδείς</span>, <span class=\"greek\">μηδεμία</span>, <span class=\"greek\">μηδέν</span> (Hom.+.—Quanto a <span class=\"greek\">μηθέν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:33</a>; IRo 4:2; 5:3; Hm 2:6, forma frequentemente encontrada desde Aristot. na literatura, inscrições [Meisterhans^3-Schw. 258f] e papiros [Mayser 180–82], ver B-D-F §33; Mlt-H. 111; Thumb 14. O uso na LXX em Thackeray 58–62; EpArist 182).</p><p class=\"entry-text\">① Como adjetivo, relativo à inexistência de qualquer um, nenhum: <span class=\"greek\">μηδεμία</span> <span class=\"greek\">αἰτία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:28</a>; 28:18. Cf. 25:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:2</a>.—Empregado com outra negação (En 98:3 <span class=\"greek\">μηδὲ</span> <span class=\"greek\">φρόνησιν</span> <span class=\"greek\">μηδεμίαν</span>; Just., D. 110, 2 <span class=\"greek\">μηδενὸς</span> <span class=\"greek\">μηδέπω</span> <span class=\"greek\">καρποῦ</span>…<span class=\"greek\">γενομένου</span>; Ath. R. 19 p. 72, 4 <span class=\"greek\">μηδεμία</span> <span class=\"greek\">μηδαμοῦ</span>…<span class=\"greek\">κρίσις</span>), nenhum... absolutamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:3</a>; 13:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:6</a>. <span class=\"greek\">κατά</span> <span class=\"greek\">μηδένα</span> <span class=\"greek\">τρόπον</span> (<span class=\"greek\">τρόπος</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:3</a>.</p><p class=\"entry-text\">② Como substantivo, referência negativa a entidade, acontecimento ou condição.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">μηδείς</span>, ninguém: <span class=\"greek\">ἀκούοντες</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">φωνῆς</span> <span class=\"greek\">μηδένα</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">θεωροῦντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:7</a>. <span class=\"greek\">μηδενὶ</span> <span class=\"greek\">εἴπῃς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:4</a>; cf. 9:30; 16:20; 17:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:43</a>; 7:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:14</a>; 5:14; 10:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:24</a> P66; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:18</a>; 10:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:11</a> e frequentemente.—Empregado com outra negação: ninguém absolutamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:17</a>.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">μηδέν</span>, nada.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">μηδὲν</span> <span class=\"greek\">αἴρειν</span> <span class=\"greek\">εἰς</span> (<span class=\"greek\">τὴν</span>) <span class=\"greek\">ὁδόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:3</a>. Cf. 6:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:25</a>, 27. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μηδενός</span>, do nada, isto é, sem qualquer motivo válido Hm 5, 2, 2.—Empregado com outra negação (Lucian, Dial. Deor. 24, 1 <span class=\"greek\">μὴ</span> <span class=\"greek\">λέγε</span> <span class=\"greek\">τοιοῦτον</span> <span class=\"greek\">μηδέν</span> = “coisa alguma”; X. Eph. 356, 11 H.) <span class=\"greek\">ὅρα</span> <span class=\"greek\">μηδενὶ</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">εἴπῃς</span>, cuida de não dizer nada a ninguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:44</a> (cf. ApcMos 3 <span class=\"greek\">μὴ</span> <span class=\"greek\">εἴπῃς</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">μηδέν</span>; Just., D. 23, 3 <span class=\"greek\">μηδὲν</span> <span class=\"greek\">μηδένος</span> <span class=\"greek\">ἀποκρινομένου</span>) <span class=\"greek\">μηδενὶ</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ὀφείλετε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:8</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:28</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Como acusativo de objeto interno, <span class=\"greek\">μηδέν</span> pode ser traduzido por não... de modo algum, absolutamente não (Aeschyl., Pla.; também Lucian, Dial. Deor. 2, 4, Tim. 43; PHib 43, 6 [III a.C.]; PAmh 111, 20; 2 Macc 14:28; 3 Macc 3:9; Jos., Ant. 14, 402; Ath. 20, 4 <span class=\"greek\">μ</span>. <span class=\"greek\">διενηνόχασιν</span>) <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ὠφεληθεῖσα</span>, ela não recebeu benefício algum <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:26</a>. <span class=\"greek\">μηδὲν</span> <span class=\"greek\">βλάψαν</span> <span class=\"greek\">αὐτόν</span>, sem prejudicá-lo de modo algum <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:35</a> (Just., D. 35, 1 <span class=\"greek\">μηδὲν</span>…<span class=\"greek\">βλάπτεσθαι</span>).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:21</a>; 10:20; 11:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:10</a> (variante de leitura <span class=\"greek\">μή</span>). <span class=\"greek\">μεριμνᾶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:6</a>. <span class=\"greek\">ὑστερεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:5</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐμποδίζειν</span> 1 Cl 20:2. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐναντιοῦσθαι</span> 61:1. <span class=\"greek\">ὅλως</span> <span class=\"greek\">μ</span>. <span class=\"greek\">διψυχήσῃς</span>, não duvides absolutamente nada Hs 6, 1, 2; <span class=\"greek\">ὅλως</span> <span class=\"greek\">μ</span>. <span class=\"greek\">σπλαγχνιζόμενος</span>, sem compaixão alguma Hs 6, 3, 2; <span class=\"greek\">μ</span>. <span class=\"greek\">ἀδικεῖσθαι</span>, não sofrer prejuízo algum Dg 6:5.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">μηδὲν</span> <span class=\"greek\">εἶναι</span>, ser nada = não valer nada, não ser ninguém (Soph., Aj. 767, cf. 1231; 1094; Pla., Apol. 41e) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:3</a>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">μηδενί</span>, de nenhum modo ou aspecto (Heron Alex. III p. 214, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:4</a>. Cf. também as passagens mencionadas acima, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:28</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδέποτε</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηδέποτε</span> (<span class=\"greek\">μηδέ</span>, <span class=\"greek\">ποτέ</span>), advérbio (X.; Pla. e outros; inscrições, papiros, LXX; Jos., Ant. 14, 142, Vi. 259; Just.), nunca, com particípio (Diod S 20, 78, 1; Just., A I, 49, 5; Galen, Inst. Log. 14, 7; PTebt 57, 6 [114 a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:7</a>; MPol 2:3; Hm 2:3; 10, 1, 4; Hs 8, 7, 2. Com infinitivo 16:10.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηδέπω</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηδέπω</span> (<span class=\"greek\">μηδέ</span>, <span class=\"greek\">πω</span>; partícula enclítica “até este momento, ainda”), advérbio (Aeschyl. e outros; POxy 471, 6; BGU 1210, 63; Just.; Tat. 5, 1), ainda não, com particípio (BGU 1124, 10; Jos., Ant. 17, 202; 312; Just., D. 110, 2; Tat. 5, 1) <span class=\"greek\">μ</span>. <span class=\"greek\">βλεπόμενα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:7</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μῆδος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μῆδος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aeschyl. e outros; inscrições, LXX; TestSol 15:8; TestNapht 5:8; AscIs 3:2; Joseph., SibOr), um medo, habitante da Média, onde havia uma diáspora judaica (Schürer III 5–9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:9</a>. BHHW II 1180.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0234-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηθαμῶς</h1><div class=\"entry-meta\"><span>advérbio remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηθαμῶς</span>, ver <span class=\"greek\">μηδαμῶς</span>.</p></section></article>"};
